        d_rot_vecs: Option<&[Vector3<f32>]>,
    ) -> Self {
        let n = log_scales.len();
        if n == 0 {
            return Self::default();
        }

        // Compute scale statistics
        let mut scales_linear: Vec<f32> = log_scales
            .iter()

