//!
//! Pass Criteria:
//! - PSNR within 2 dB of reference (33.0 - 37.0 dB)
//! - SSIM within 0.02 of reference (0.96 - 1.00)
//! - LPIPS within 0.02 of reference (0.00 - 0.04)
//!
//! Note: This is a LONG-RUNNING test that takes several hours to complete.
//! Run with: cargo test --release --test verification_benchmark_nerf_synthetic -- --ignored --nocapture
//!
//! The test will:
//! 1. Train on NeRF Synthetic lego dataset for 30K iterations
//! 2. Evaluate on test views
//! 3. Compute PSNR, SSIM, and LPIPS metrics
//! 4. Validate against reference values

use nalgebra::{Matrix3, Vector3};
use std::path::{Path, PathBuf};
use sugar_rs::core::{init_from_colmap_points_visible_stratified, Camera, Gaussian, GaussianCloud};
use sugar_rs::io::load_colmap_scene;
use sugar_rs::optim::adam::{AdamF32, AdamSh16, AdamSo3, AdamVec3};
use sugar_rs::optim::loss::{l1_dssim_image_loss_and_grad_weighted, LossKind};
use sugar_rs::render::full_diff::{
    downsample_rgb_bilinear, linear_vec_to_rgb8_img, render_full_color_grads, render_full_linear,
    rgb8_to_linear_vec,
};
use image::RgbImage;

const DATASET_PATH: &str = "datasets/nerf_synthetic/lego";

/// Helper: Compute PSNR between rendered and target images
fn compute_psnr(rendered: &[Vector3<f32>], target: &[Vector3<f32>]) -> f32 {
    let mse: f32 = rendered
        .iter()
        .zip(target.iter())
        .map(|(a, b)| (a - b).norm_squared())
        .sum::<f32>()
        / (rendered.len() as f32);

    if mse < 1e-10 {
        return 100.0; // Perfect match
    }

    20.0 * (1.0_f32).log10() - 10.0 * mse.log10()
}

/// Helper: Simplified SSIM computation (luminance-based approximation)
fn compute_ssim(rendered: &[Vector3<f32>], target: &[Vector3<f32>]) -> f32 {
    let n = rendered.len() as f32;

    // Convert RGB to luminance (grayscale)
    let rendered_lum: Vec<f32> = rendered
        .iter()
        .map(|rgb| 0.299 * rgb.x + 0.587 * rgb.y + 0.114 * rgb.z)
        .collect();
    let target_lum: Vec<f32> = target
        .iter()
        .map(|rgb| 0.299 * rgb.x + 0.587 * rgb.y + 0.114 * rgb.z)
        .collect();

    // Compute means
    let mu_x: f32 = rendered_lum.iter().sum::<f32>() / n;
    let mu_y: f32 = target_lum.iter().sum::<f32>() / n;

    // Compute variances and covariance
    let var_x: f32 = rendered_lum.iter().map(|v| (v - mu_x).powi(2)).sum::<f32>() / n;
    let var_y: f32 = target_lum.iter().map(|v| (v - mu_y).powi(2)).sum::<f32>() / n;
    let cov_xy: f32 = rendered_lum
        .iter()
        .zip(target_lum.iter())
        .map(|(x, y)| (x - mu_x) * (y - mu_y))
        .sum::<f32>()
        / n;

    // SSIM constants
    let c1 = (0.01_f32).powi(2);
    let c2 = (0.03_f32).powi(2);

    // SSIM formula
    let numerator = (2.0 * mu_x * mu_y + c1) * (2.0 * cov_xy + c2);
    let denominator = (mu_x * mu_x + mu_y * mu_y + c1) * (var_x + var_y + c2);

    numerator / denominator
}

/// Helper: Load NeRF Synthetic dataset transforms
fn load_nerf_synthetic_transforms(
    dataset_path: &Path,
    split: &str, // "train", "val", or "test"
) -> Result<Vec<(PathBuf, Camera)>, String> {
    use serde_json::Value;
    use std::fs;

    let transforms_path = dataset_path.join(format!("transforms_{}.json", split));
    let content = fs::read_to_string(&transforms_path)
        .map_err(|e| format!("Failed to read {}: {}", transforms_path.display(), e))?;

    let json: Value = serde_json::from_str(&content)
        .map_err(|e| format!("Failed to parse JSON: {}", e))?;

    // Extract camera parameters
    let camera_angle_x = json["camera_angle_x"]
        .as_f64()
        .ok_or("Missing camera_angle_x")?;

    // NeRF Synthetic uses 800×800 images
    let width = 800;
    let height = 800;

    // Compute focal length from field of view
    let focal = (width as f64) / (2.0 * (camera_angle_x / 2.0).tan());
    let fx = focal as f32;
    let fy = focal as f32;
    let cx = (width as f32) / 2.0;
    let cy = (height as f32) / 2.0;

    // Parse frames
    let frames = json["frames"]
        .as_array()
        .ok_or("Missing frames array")?;

    let mut cameras = Vec::new();

    for frame in frames {
        let file_path = frame["file_path"]
            .as_str()
            .ok_or("Missing file_path")?;

        // Construct full image path
