            t[i] = transform[i][3].as_f64().unwrap() as f32;
        }

        // NeRF uses camera-to-world, we need world-to-camera
        // world-to-camera: R_wc = R^T, t_wc = -R^T * t
        let R_wc = R.transpose();
        let t_wc = -R_wc * t;

        // Create camera
        let camera = Camera::new(fx, fy, cx, cy, width, height, R_wc, t_wc);

        cameras.push((img_path, camera));
    }

    Ok(cameras)
}

