        let target_linear = rgb8_to_linear_vec(target_img);

        // Downsample target
        let downsampled_width = ((camera.width as f32) * downsample_factor) as usize;
        let downsampled_height = ((camera.height as f32) * downsample_factor) as usize;
        let target_downsampled = downsample_rgb_bilinear(
            &target_linear,
            camera.width,
            camera.height,
            downsampled_width,
            downsampled_height,
        );

        // Render and compute gradients
        let (rendered, d_positions, d_log_scales, d_rot_vecs, d_opacity_logits, d_sh_coeffs) =
            render_full_color_grads(
                &gaussians,
                camera,
                &background,
                downsampled_width,
                downsampled_height,
                false, // enable_timing
            );

        // Compute loss and gradients
        let (loss, d_rendered) = l1_dssim_image_loss_and_grad_weighted(
            &rendered,
            &target_downsampled,
            downsampled_width,
            downsampled_height,
            0.2, // lambda (L1 weight)
        );

        // Apply gradients (simplified - in practice, need to backprop d_rendered through renderer)
        // For now, we'll use the gradients directly from render_full_color_grads

        // Update parameters
        for i in 0..gaussians.len() {
            gaussians[i].position = opt_positions.step(i, &gaussians[i].position, &d_positions[i]);
            gaussians[i].log_scale = opt_log_scales.step(i, &gaussians[i].log_scale, &d_log_scales[i]);

            // Update rotation (quaternion)
            let rot_vec = Vector3::new(
                gaussians[i].rotation.as_ref().coords[0],
                gaussians[i].rotation.as_ref().coords[1],
                gaussians[i].rotation.as_ref().coords[2],
            );
            let new_rot_vec = opt_rot_vecs.step(i, &rot_vec, &d_rot_vecs[i]);
            gaussians[i].rotation = nalgebra::UnitQuaternion::from_scaled_axis(new_rot_vec);

            gaussians[i].opacity = opt_opacity_logits.step(i, gaussians[i].opacity, d_opacity_logits[i]);
            gaussians[i].sh_coeffs = opt_sh_coeffs.step(i, &gaussians[i].sh_coeffs, &d_sh_coeffs[i]);
        }

        // Log progress
        if (iter + 1) % log_interval == 0 || iter == 0 {
            let psnr = compute_psnr(&rendered, &target_downsampled);
            println!(
                "Iteration {:5}/{:5}  Loss: {:.6}  PSNR: {:.2} dB  Gaussians: {}",
                iter + 1,
                n_iterations,
                loss,
                psnr,
                gaussians.len()
            );
        }
    }

    println!("\n=== Training Complete ===\n");

    // Evaluate on test set
    println!("=== Test Set Evaluation ===\n");

    let mut psnr_values = Vec::new();
    let mut ssim_values = Vec::new();

    for (test_idx, (img_path, test_camera)) in test_data.iter().enumerate() {
        // Load test image
        let test_img = image::open(img_path)
            .expect(&format!("Failed to load test image: {}", img_path.display()))
            .to_rgb8();

        let test_linear = rgb8_to_linear_vec(&test_img);

        // Render at full resolution
        let rendered = render_full_linear(
            &gaussians,
            test_camera,
            &background,
            test_camera.width,
            test_camera.height,
            false, // enable_timing
        );

        // Compute metrics
        let psnr = compute_psnr(&rendered, &test_linear);
        let ssim = compute_ssim(&rendered, &test_linear);

        psnr_values.push(psnr);
        ssim_values.push(ssim);

        if test_idx < 5 {
            println!("  Test view {}: PSNR = {:.2} dB, SSIM = {:.4}", test_idx + 1, psnr, ssim);
        }
    }

    // Compute average metrics
    let avg_psnr = psnr_values.iter().sum::<f32>() / psnr_values.len() as f32;
    let avg_ssim = ssim_values.iter().sum::<f32>() / ssim_values.len() as f32;

    println!("\n=== Final Results ===");
    println!("  Average PSNR: {:.2} dB", avg_psnr);
    println!("  Average SSIM: {:.4}", avg_ssim);
    println!("  LPIPS: Not implemented (requires external library)");

    println!("\n=== Reference Metrics (3DGS paper) ===");
    println!("  PSNR: ~35.0 dB");
    println!("  SSIM: ~0.98");
    println!("  LPIPS: ~0.02");

    println!("\n=== Validation ===");

    // Validate PSNR (33.0 - 37.0 dB)
    let psnr_pass = avg_psnr >= 33.0 && avg_psnr <= 37.0;
    println!(
        "  PSNR: {:.2} dB [{}] (expected: 33.0 - 37.0 dB)",
        avg_psnr,
        if psnr_pass { "PASS" } else { "FAIL" }
    );

    // Validate SSIM (0.96 - 1.00)
    let ssim_pass = avg_ssim >= 0.96 && avg_ssim <= 1.00;
    println!(
        "  SSIM: {:.4} [{}] (expected: 0.96 - 1.00)",
        avg_ssim,
        if ssim_pass { "PASS" } else { "FAIL" }
    );

    // LPIPS not implemented yet
    println!("  LPIPS: Not implemented [SKIP]");

    println!();

    // Assert pass criteria
    assert!(
        psnr_pass,
        "PSNR {:.2} dB is outside acceptable range [33.0, 37.0] dB",
        avg_psnr
    );
    assert!(
        ssim_pass,
        "SSIM {:.4} is outside acceptable range [0.96, 1.00]",
        avg_ssim
    );

    println!("=== TC-OPT-012: PASS ===\n");
}

