//! TC-OPT-012: NeRF Synthetic Benchmark
//!
//! This test verifies that the implementation achieves expected quality on the
//! standard NeRF Synthetic 'lego' scene after 30,000 training iterations.
//!
//! Reference Metrics (from 3DGS paper):
//! - PSNR: ~35.0 dB
//! - SSIM: ~0.98
//! - LPIPS: ~0.02
//!
//! Pass Criteria:
//! - PSNR within 2 dB of reference (33.0 - 37.0 dB)
//! - SSIM within 0.02 of reference (0.96 - 1.00)
//! - LPIPS within 0.02 of reference (0.00 - 0.04)
//!
//! Note: This is a LONG-RUNNING test that takes several hours to complete.
//! Run with: cargo test --release --test verification_benchmark_nerf_synthetic -- --ignored --nocapture
//!
//! The test will:
//! 1. Train on NeRF Synthetic lego dataset for 30K iterations
//! 2. Evaluate on test views
//! 3. Compute PSNR, SSIM, and LPIPS metrics
//! 4. Validate against reference values

use nalgebra::{Matrix3, Vector3};
use std::path::{Path, PathBuf};
use sugar_rs::core::{init_from_colmap_points_visible_stratified, Camera, Gaussian, GaussianCloud};
use sugar_rs::io::load_colmap_scene;
use sugar_rs::optim::adam::{AdamF32, AdamSh16, AdamSo3, AdamVec3};
use sugar_rs::optim::loss::{l1_dssim_image_loss_and_grad_weighted, LossKind};
use sugar_rs::render::full_diff::{
    downsample_rgb_bilinear, linear_vec_to_rgb8_img, render_full_color_grads, render_full_linear,
    rgb8_to_linear_vec,
};
use image::RgbImage;

const DATASET_PATH: &str = "datasets/nerf_synthetic/lego";

/// Helper: Compute PSNR between rendered and target images
fn compute_psnr(rendered: &[Vector3<f32>], target: &[Vector3<f32>]) -> f32 {
    let mse: f32 = rendered
        .iter()
        .zip(target.iter())
        .map(|(a, b)| (a - b).norm_squared())
        .sum::<f32>()
        / (rendered.len() as f32);

    if mse < 1e-10 {
        return 100.0; // Perfect match
    }

    20.0 * (1.0_f32).log10() - 10.0 * mse.log10()
}

/// Helper: Simplified SSIM computation (luminance-based approximation)
fn compute_ssim(rendered: &[Vector3<f32>], target: &[Vector3<f32>]) -> f32 {
    let n = rendered.len() as f32;

    // Convert RGB to luminance (grayscale)
    let rendered_lum: Vec<f32> = rendered
        .iter()
        .map(|rgb| 0.299 * rgb.x + 0.587 * rgb.y + 0.114 * rgb.z)
        .collect();
    let target_lum: Vec<f32> = target
        .iter()
        .map(|rgb| 0.299 * rgb.x + 0.587 * rgb.y + 0.114 * rgb.z)
        .collect();

    // Compute means
    let mu_x: f32 = rendered_lum.iter().sum::<f32>() / n;
    let mu_y: f32 = target_lum.iter().sum::<f32>() / n;

    // Compute variances and covariance
    let var_x: f32 = rendered_lum.iter().map(|v| (v - mu_x).powi(2)).sum::<f32>() / n;
    let var_y: f32 = target_lum.iter().map(|v| (v - mu_y).powi(2)).sum::<f32>() / n;
    let cov_xy: f32 = rendered_lum
        .iter()
        .zip(target_lum.iter())
        .map(|(x, y)| (x - mu_x) * (y - mu_y))
        .sum::<f32>()
        / n;

    // SSIM constants
    let c1 = (0.01_f32).powi(2);
    let c2 = (0.03_f32).powi(2);

    // SSIM formula
    let numerator = (2.0 * mu_x * mu_y + c1) * (2.0 * cov_xy + c2);
    let denominator = (mu_x * mu_x + mu_y * mu_y + c1) * (var_x + var_y + c2);

    numerator / denominator
}

/// Helper: Load NeRF Synthetic dataset transforms
fn load_nerf_synthetic_transforms(
    dataset_path: &Path,
    split: &str, // "train", "val", or "test"
) -> Result<Vec<(PathBuf, Camera)>, String> {
    use serde_json::Value;
    use std::fs;

    let transforms_path = dataset_path.join(format!("transforms_{}.json", split));
    let content = fs::read_to_string(&transforms_path)
        .map_err(|e| format!("Failed to read {}: {}", transforms_path.display(), e))?;

    let json: Value = serde_json::from_str(&content)
        .map_err(|e| format!("Failed to parse JSON: {}", e))?;

    // Extract camera parameters
    let camera_angle_x = json["camera_angle_x"]
        .as_f64()
        .ok_or("Missing camera_angle_x")?;

    // NeRF Synthetic uses 800×800 images
    let width = 800;
    let height = 800;

    // Compute focal length from field of view
    let focal = (width as f64) / (2.0 * (camera_angle_x / 2.0).tan());
    let fx = focal as f32;
    let fy = focal as f32;
    let cx = (width as f32) / 2.0;
    let cy = (height as f32) / 2.0;

    // Parse frames
    let frames = json["frames"]
        .as_array()
        .ok_or("Missing frames array")?;

    let mut cameras = Vec::new();

    for frame in frames {
        let file_path = frame["file_path"]
            .as_str()
            .ok_or("Missing file_path")?;

        // Construct full image path
        let img_path = dataset_path.join(format!("{}.png", file_path));

        // Parse transform matrix (4×4 camera-to-world)
        let transform = frame["transform_matrix"]
            .as_array()
            .ok_or("Missing transform_matrix")?;

        // Extract 3×3 rotation and translation
        let mut R = Matrix3::<f32>::zeros();
        let mut t = Vector3::<f32>::zeros();

        for i in 0..3 {
            for j in 0..3 {
                R[(i, j)] = transform[i][j].as_f64().unwrap() as f32;
            }
            t[i] = transform[i][3].as_f64().unwrap() as f32;
        }

        // NeRF uses camera-to-world, we need world-to-camera
        // world-to-camera: R_wc = R^T, t_wc = -R^T * t
        let R_wc = R.transpose();
        let t_wc = -R_wc * t;

        // Create camera
        let camera = Camera::new(fx, fy, cx, cy, width, height, R_wc, t_wc);

        cameras.push((img_path, camera));
    }

    Ok(cameras)
}

/// TC-OPT-012: NeRF Synthetic Benchmark
///
/// This test runs a full 30K iteration training on the NeRF Synthetic lego dataset
/// and validates that the final metrics match reference values from the 3DGS paper.
///
/// Pass Criteria:
/// - PSNR: 33.0 - 37.0 dB (reference: ~35.0 dB, tolerance: ±2 dB)
/// - SSIM: 0.96 - 1.00 (reference: ~0.98, tolerance: ±0.02)
/// - LPIPS: 0.00 - 0.04 (reference: ~0.02, tolerance: ±0.02)
#[test]
#[ignore] // Long-running test, run explicitly with --ignored
fn tc_opt_012_nerf_synthetic_benchmark() {
    println!("\n=== TC-OPT-012: NeRF Synthetic Benchmark ===\n");
    println!("Note: This test runs 30,000 training iterations and may take several hours.");
    println!("Progress will be logged every 1000 iterations.\n");

    // Check dataset exists
    let dataset_path = PathBuf::from(DATASET_PATH);
    if !dataset_path.exists() {
        panic!(
            "Dataset not found at {}. Please download the NeRF Synthetic lego dataset first.",
            DATASET_PATH
        );
    }

    // Load training cameras and images
    println!("Loading training data...");
    let train_data = load_nerf_synthetic_transforms(&dataset_path, "train")
        .expect("Failed to load training transforms");
    println!("  Training views: {}", train_data.len());

    // Load test cameras and images
    println!("Loading test data...");
    let test_data = load_nerf_synthetic_transforms(&dataset_path, "test")
        .expect("Failed to load test transforms");
    println!("  Test views: {}", test_data.len());

    // Load training images
    let mut train_images: Vec<RgbImage> = Vec::new();
    let mut train_cameras: Vec<Camera> = Vec::new();

    for (img_path, camera) in &train_data {
        let img = image::open(img_path)
            .expect(&format!("Failed to load image: {}", img_path.display()))
            .to_rgb8();
        train_images.push(img);
        train_cameras.push(*camera);
    }

    // Initialize Gaussians from point cloud
    println!("\nInitializing Gaussians...");
    let ply_path = dataset_path.join("lego.ply");

    // For NeRF Synthetic, we don't have COLMAP data, so we'll initialize from the PLY
    // This is a simplified initialization - in practice, you'd want proper COLMAP data
    let mut gaussians = Vec::new();

    // Load PLY points (NeRF Synthetic includes a dense point cloud)
    // For now, we'll create a simple grid initialization as a placeholder
    // TODO: Implement proper PLY loading or COLMAP-style initialization

    println!("Warning: Using simplified initialization. For best results, use COLMAP reconstruction.");

    // Create grid of initial Gaussians covering [-1, 1]^3 space
    let grid_size = 10;
    for i in 0..grid_size {
        for j in 0..grid_size {
            for k in 0..grid_size {
                let x = -1.0 + 2.0 * (i as f32) / (grid_size as f32 - 1.0);
                let y = -1.0 + 2.0 * (j as f32) / (grid_size as f32 - 1.0);
                let z = -1.0 + 2.0 * (k as f32) / (grid_size as f32 - 1.0);

                let position = Vector3::new(x, y, z);
                let log_scale = Vector3::new(-2.0, -2.0, -2.0); // Small initial scale
                let rotation = nalgebra::UnitQuaternion::identity();
                let opacity = 0.0; // logit space (sigmoid(0) = 0.5)
                let sh_coeffs = [[0.0f32; 3]; 16]; // Black initially

                gaussians.push(Gaussian {
                    position,
                    log_scale,
                    rotation,
                    opacity,
                    sh_coeffs,
                });
            }
        }
    }

    println!("  Initial Gaussians: {}", gaussians.len());

    // Training configuration (matching "full" preset)
    let n_iterations = 30_000;
    let lr_position = 0.00016;
    let lr_scale = 0.005;
    let lr_rotation = 0.001;
    let lr_opacity = 0.05;
    let lr_sh = 0.0025;
    let downsample_factor = 0.4; // 40% resolution
    let log_interval = 1000;

    // Initialize optimizers
    let mut opt_positions = AdamVec3::new(lr_position, 0.9, 0.999, 1e-15, gaussians.len());
    let mut opt_log_scales = AdamVec3::new(lr_scale, 0.9, 0.999, 1e-15, gaussians.len());
    let mut opt_rot_vecs = AdamSo3::new(lr_rotation, 0.9, 0.999, 1e-15, gaussians.len());
    let mut opt_opacity_logits = AdamF32::new(lr_opacity, 0.9, 0.999, 1e-15, gaussians.len());
    let mut opt_sh_coeffs = AdamSh16::new(lr_sh, 0.9, 0.999, 1e-15, gaussians.len());

    let mut background = Vector3::new(0.0, 0.0, 0.0);

    println!("\n=== Training Configuration ===");
    println!("  Iterations: {}", n_iterations);
    println!("  Downsampling: {:.1}%", downsample_factor * 100.0);
    println!("  Learning rates:");
    println!("    Position: {}", lr_position);
    println!("    Scale: {}", lr_scale);
    println!("    Rotation: {}", lr_rotation);
    println!("    Opacity: {}", lr_opacity);
    println!("    SH: {}", lr_sh);

    println!("\n=== Training Progress ===\n");

    // Training loop
    use rand::seq::SliceRandom;
    use rand::SeedableRng;
    let mut rng = rand::rngs::StdRng::seed_from_u64(123);

    let mut train_indices: Vec<usize> = (0..train_images.len()).collect();

    for iter in 0..n_iterations {
        // Shuffle training data each epoch
        if iter % train_images.len() == 0 {
            train_indices.shuffle(&mut rng);
        }

        // Select random training view
        let idx = train_indices[iter % train_images.len()];
        let camera = &train_cameras[idx];
        let target_img = &train_images[idx];

        // Convert target to linear RGB
        let target_linear = rgb8_to_linear_vec(target_img);

        // Downsample target
        let downsampled_width = ((camera.width as f32) * downsample_factor) as usize;
        let downsampled_height = ((camera.height as f32) * downsample_factor) as usize;
        let target_downsampled = downsample_rgb_bilinear(
            &target_linear,
            camera.width,
            camera.height,
            downsampled_width,
            downsampled_height,
        );

        // Render and compute gradients
        let (rendered, d_positions, d_log_scales, d_rot_vecs, d_opacity_logits, d_sh_coeffs) =
            render_full_color_grads(
                &gaussians,
                camera,
                &background,
                downsampled_width,
                downsampled_height,
                false, // enable_timing
            );

        // Compute loss and gradients
        let (loss, d_rendered) = l1_dssim_image_loss_and_grad_weighted(
            &rendered,
            &target_downsampled,
            downsampled_width,
            downsampled_height,
            0.2, // lambda (L1 weight)
        );

        // Apply gradients (simplified - in practice, need to backprop d_rendered through renderer)
        // For now, we'll use the gradients directly from render_full_color_grads

        // Update parameters
        for i in 0..gaussians.len() {
            gaussians[i].position = opt_positions.step(i, &gaussians[i].position, &d_positions[i]);
            gaussians[i].log_scale = opt_log_scales.step(i, &gaussians[i].log_scale, &d_log_scales[i]);

            // Update rotation (quaternion)
            let rot_vec = Vector3::new(
                gaussians[i].rotation.as_ref().coords[0],
                gaussians[i].rotation.as_ref().coords[1],
                gaussians[i].rotation.as_ref().coords[2],
            );
            let new_rot_vec = opt_rot_vecs.step(i, &rot_vec, &d_rot_vecs[i]);
            gaussians[i].rotation = nalgebra::UnitQuaternion::from_scaled_axis(new_rot_vec);

            gaussians[i].opacity = opt_opacity_logits.step(i, gaussians[i].opacity, d_opacity_logits[i]);
            gaussians[i].sh_coeffs = opt_sh_coeffs.step(i, &gaussians[i].sh_coeffs, &d_sh_coeffs[i]);
        }

        // Log progress
        if (iter + 1) % log_interval == 0 || iter == 0 {
            let psnr = compute_psnr(&rendered, &target_downsampled);
            println!(
                "Iteration {:5}/{:5}  Loss: {:.6}  PSNR: {:.2} dB  Gaussians: {}",
                iter + 1,
                n_iterations,
                loss,
                psnr,
                gaussians.len()
            );
        }
    }

    println!("\n=== Training Complete ===\n");

    // Evaluate on test set
    println!("=== Test Set Evaluation ===\n");

    let mut psnr_values = Vec::new();
    let mut ssim_values = Vec::new();

    for (test_idx, (img_path, test_camera)) in test_data.iter().enumerate() {
        // Load test image
        let test_img = image::open(img_path)
            .expect(&format!("Failed to load test image: {}", img_path.display()))
            .to_rgb8();

        let test_linear = rgb8_to_linear_vec(&test_img);

        // Render at full resolution
        let rendered = render_full_linear(
            &gaussians,
            test_camera,
            &background,
            test_camera.width,
            test_camera.height,
            false, // enable_timing
        );

        // Compute metrics
        let psnr = compute_psnr(&rendered, &test_linear);
        let ssim = compute_ssim(&rendered, &test_linear);

        psnr_values.push(psnr);
        ssim_values.push(ssim);

        if test_idx < 5 {
            println!("  Test view {}: PSNR = {:.2} dB, SSIM = {:.4}", test_idx + 1, psnr, ssim);
        }
    }

    // Compute average metrics
    let avg_psnr = psnr_values.iter().sum::<f32>() / psnr_values.len() as f32;
    let avg_ssim = ssim_values.iter().sum::<f32>() / ssim_values.len() as f32;

    println!("\n=== Final Results ===");
    println!("  Average PSNR: {:.2} dB", avg_psnr);
    println!("  Average SSIM: {:.4}", avg_ssim);
    println!("  LPIPS: Not implemented (requires external library)");

    println!("\n=== Reference Metrics (3DGS paper) ===");
    println!("  PSNR: ~35.0 dB");
    println!("  SSIM: ~0.98");
    println!("  LPIPS: ~0.02");

    println!("\n=== Validation ===");

    // Validate PSNR (33.0 - 37.0 dB)
    let psnr_pass = avg_psnr >= 33.0 && avg_psnr <= 37.0;
    println!(
        "  PSNR: {:.2} dB [{}] (expected: 33.0 - 37.0 dB)",
        avg_psnr,
        if psnr_pass { "PASS" } else { "FAIL" }
    );

    // Validate SSIM (0.96 - 1.00)
    let ssim_pass = avg_ssim >= 0.96 && avg_ssim <= 1.00;
    println!(
        "  SSIM: {:.4} [{}] (expected: 0.96 - 1.00)",
        avg_ssim,
        if ssim_pass { "PASS" } else { "FAIL" }
    );

    // LPIPS not implemented yet
    println!("  LPIPS: Not implemented [SKIP]");

    println!();

    // Assert pass criteria
    assert!(
        psnr_pass,
        "PSNR {:.2} dB is outside acceptable range [33.0, 37.0] dB",
        avg_psnr
    );
    assert!(
        ssim_pass,
        "SSIM {:.4} is outside acceptable range [0.96, 1.00]",
        avg_ssim
    );

    println!("=== TC-OPT-012: PASS ===\n");
}
